    void buildUi(){ ScrollView root=new ScrollView(this); LinearLayout col=new LinearLayout(this); col.setOrientation(LinearLayout.VERTICAL); col.setPadding(22,22,22,22); col.setBackgroundColor(BG); root.addView(col); TextView title=t("ESP32 BLE Tracker",30,CYAN,true); title.setGravity(Gravity.CENTER); col.addView(title); note=t("Radar uses calibrated RSSI distance bands. Sweep mode can show a strongest-signal heading hint only; it is not true BLE AoA.",13,AMBER,false); col.addView(card(note)); indicators=row(); phoneLed=chip("PHONE BLE",AMBER); espLed=chip("ESP32 BLE",RED); wifiLed=chip("REMOTE WI-FI",RED); gpsLed=chip("GPS",RED); compassLed=chip("COMPASS",RED); indicators.addView(phoneLed); indicators.addView(espLed); indicators.addView(wifiLed); indicators.addView(gpsLed); indicators.addView(compassLed); col.addView(indicators); setup=new LinearLayout(this); setup.setOrientation(LinearLayout.VERTICAL); col.addView(card(setup)); addControls(); radar=new RadarView(this); radar.devices=devices; col.addView(card(radar), new LinearLayout.LayoutParams(-1,650)); stats=t("Idle",14,0xffe8fbff,false); col.addView(card(stats)); mapFrame=new FrameLayout(this); map=new MapView(this); map.setTileSource(TileSourceFactory.MAPNIK); map.setMultiTouchControls(true); map.getController().setZoom(17.0); mapFrame.addView(map,new FrameLayout.LayoutParams(-1,520)); col.addView(card(mapFrame)); list=new LinearLayout(this); list.setOrientation(LinearLayout.VERTICAL); col.addView(list); setContentView(root); }
