    void addControls(){ Spinner src=new Spinner(this); src.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Phone BLE scanner","ESP32S3 scanner"})); setup.addView(label("Detection source")); setup.addView(src); Spinner transport=new Spinner(this); transport.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Direct BLE GATT connectable mode","Remote Wi-Fi HTTP (recommended scanner/tracker)"})); transport.setSelection(1); setup.addView(label("ESP32 transport")); setup.addView(transport); EditText host=edit("ESP32 Wi-Fi URL, e.g. http://192.168.4.1/scan","http://192.168.4.1/scan"); EditText mac=edit("Track target MAC/address (optional)",""); EditText name=edit("Track target name contains (optional)",""); EditText meters=edit("Near distance threshold meters","5"); EditText min=edit("Min RSSI dBm","-100"); EditText ref=edit("Reference RSSI @1m","-59"); EditText ple=edit("Path-loss exponent (2.0 open, 3.0 default, 4.0 indoor)","3.0"); LinearLayout presets=row(); Button open=new Button(this); open.setText("OPEN CAL"); open.setOnClickListener(v->{ref.setText("-55"); ple.setText("2.2");}); Button indoor=new Button(this); indoor.setText("INDOOR CAL"); indoor.setOnClickListener(v->{ref.setText("-62"); ple.setText("3.4");}); presets.addView(open); presets.addView(indoor); setup.addView(presets); Spinner mode=new Spinner(this); mode.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Scanner: reliable real-time tracking","Direct GATT: phone connects, scanning paused","Hybrid/Auto: safe scanner-first"})); setup.addView(label("ESP32 Bluetooth mode")); setup.addView(mode); trackStatus=t("Tracking: off",14,AMBER,true); setup.addView(trackStatus); sweepStatus=t("Sweep: off • rotate slowly while target is tracked",13,AMBER,false); setup.addView(sweepStatus); CheckBox gps=new CheckBox(this); gps.setText("Use phone GPS fallback when ESP32 GPS is absent"); gps.setTextColor(Color.WHITE); gps.setChecked(true); setup.addView(gps); Button apply=new Button(this); apply.setText("APPLY TRACKING / SETTINGS"); apply.setOnClickListener(v->{ cfg.source=src.getSelectedItemPosition(); cfg.transport=transport.getSelectedItemPosition(); cfg.host=host.getText().toString(); cfg.mac=mac.getText().toString().trim().toUpperCase(); cfg.name=name.getText().toString(); cfg.meters=dbl(meters,5); cfg.minRssi=num(min,-100); cfg.ref=num(ref,-59); cfg.pathLoss=Math.max(1.6,Math.min(5.5,dbl(ple,3.0))); cfg.gps=gps.isChecked(); if(cfg.gps)startLocation(); else stopLocation(); log("Settings applied; ref="+cfg.ref+"dBm path-loss="+cfg.pathLoss+" target="+(cfg.mac.length()>0?cfg.mac:cfg.name)); sendTrackToEsp(); }); setup.addView(apply); sweepBtn=new Button(this); sweepBtn.setText("START COMPASS SWEEP"); sweepBtn.setOnClickListener(v->toggleSweep()); setup.addView(sweepBtn); Button modeBtn=new Button(this); modeBtn.setText("SEND ESP32 MODE"); modeBtn.setOnClickListener(v->{ String m=mode.getSelectedItemPosition()==0?"scanner":mode.getSelectedItemPosition()==1?"gatt":"hybrid"; sendModeToEsp(m); }); setup.addView(modeBtn); Button logsBtn=new Button(this); logsBtn.setText("TERMINAL / LOGS"); logsBtn.setOnClickListener(v->showLogs()); setup.addView(logsBtn); scanBtn=new Button(this); scanBtn.setText("START PHONE SCAN"); scanBtn.setOnClickListener(v->{ if(scanning)stop(); else startPhoneScan(); }); setup.addView(scanBtn); espBtn=new Button(this); espBtn.setText("DIRECT BLE GATT INFO"); espBtn.setOnClickListener(v->connectEspBle()); setup.addView(espBtn); wifiBtn=new Button(this); wifiBtn.setText("POLL ESP32 WI-FI"); wifiBtn.setOnClickListener(v->{ wifiPolling=!wifiPolling; wifiLed.setTextColor(wifiPolling?GREEN:RED); wifiBtn.setText(wifiPolling?"STOP WI-FI POLL":"POLL ESP32 WI-FI"); log(wifiPolling?"Wi-Fi polling started":"Wi-Fi polling stopped"); if(wifiPolling)pollWifi(); }); setup.addView(wifiBtn); }
    TextView label(String s){ return t(s,12,0xff9db2c0,true); } int num(EditText e,int d){ try{return Integer.parseInt(e.getText().toString().trim());}catch(Exception x){return d;} } double dbl(EditText e,double d){ try{return Double.parseDouble(e.getText().toString().trim());}catch(Exception x){return d;} } void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();} void log(String s){String line=new SimpleDateFormat("HH:mm:ss",Locale.US).format(new Date())+"  "+s; logs.addFirst(line); while(logs.size()>120)logs.removeLast();}
    void showLogs(){ TextView v=t(String.join("\n",logs),12,0xffd8f8ff,false); v.setTypeface(android.graphics.Typeface.MONOSPACE); new AlertDialog.Builder(this).setTitle("Mini terminal / ESP32 events").setView(v).setPositiveButton("CLOSE",null).show(); }
    String base(){ return cfg.host.replace("/scan","").replace("/status",""); }
    void sendModeToEsp(String mode){ if(espConnected&&espRx!=null&&writeEspRx("mode=" + mode)){ log("ESP32 GATT mode command sent -> "+mode); return; } new Thread(()->{ try{ URL u=new URL(base()+"/mode?value="+URLEncoder.encode(mode,"UTF-8")); HttpURLConnection c=(HttpURLConnection)u.openConnection(); c.setConnectTimeout(2500); c.setReadTimeout(2500); String r=new BufferedReader(new InputStreamReader(c.getInputStream())).readLine(); runOnUiThread(()->{note.setText("ESP32 mode result: "+r); log("ESP32 mode -> "+mode+": "+r);}); }catch(Exception e){runOnUiThread(()->log("ESP32 mode failed: "+e.getMessage()));} }).start(); }
    void sendTrackToEsp(){ if(cfg.source!=1)return; new Thread(()->{ try{ boolean blank=cfg.mac.length()==0&&cfg.name.trim().length()==0; String path=blank?"/track?off=1":"/track?"+(cfg.mac.length()>0?"address="+URLEncoder.encode(cfg.mac,"UTF-8"):"name="+URLEncoder.encode(cfg.name,"UTF-8"))+"&meters="+cfg.meters; URL u=new URL(base()+path); HttpURLConnection c=(HttpURLConnection)u.openConnection(); c.setConnectTimeout(2500); c.setReadTimeout(2500); String r=new BufferedReader(new InputStreamReader(c.getInputStream())).readLine(); runOnUiThread(()->log(blank?"ESP32 tracking disabled: "+r:"ESP32 tracking set: "+r)); }catch(Exception e){runOnUiThread(()->log("ESP32 tracking failed: "+e.getMessage()));} }).start(); }

    String[] perms(){ ArrayList<String> p=new ArrayList<>(); p.add(Manifest.permission.ACCESS_FINE_LOCATION); p.add(Manifest.permission.ACCESS_COARSE_LOCATION); if(Build.VERSION.SDK_INT>=31){p.add(Manifest.permission.BLUETOOTH_SCAN);p.add(Manifest.permission.BLUETOOTH_CONNECT);} return p.toArray(new String[0]); }
    boolean hasPerms(){ for(String p:perms()) if(checkSelfPermission(p)!=PackageManager.PERMISSION_GRANTED)return false; return true; } void requestPerms(){ if(!hasPerms())requestPermissions(perms(),7); }
    public void onRequestPermissionsResult(int r,String[] p,int[] g){ super.onRequestPermissionsResult(r,p,g); if(r==7&&pendingScan){pendingScan=false;startPhoneScan();} if(cfg.gps)startLocation(); }
    void startPhoneScan(){ if(!hasPerms()){pendingScan=true;requestPerms();return;} BluetoothAdapter a=((BluetoothManager)getSystemService(BLUETOOTH_SERVICE)).getAdapter(); if(a==null||!a.isEnabled()){startActivity(new Intent(Settings.ACTION_BLUETOOTH_SETTINGS));return;} ble=a.getBluetoothLeScanner(); if(ble==null){toast("BLE scanner unavailable");return;} try{ ble.startScan(null,new ScanSettings.Builder().setScanMode(ScanSettings.SCAN_MODE_LOW_LATENCY).build(),scanCb); scanning=true; phoneLed.setTextColor(GREEN); scanBtn.setText("STOP PHONE SCAN"); startLocation(); }catch(SecurityException e){toast("BLE permission denied");} }
    void stop(){ if(ble!=null)try{ble.stopScan(scanCb);}catch(Exception ignored){} scanning=false; phoneLed.setTextColor(AMBER); scanBtn.setText("START PHONE SCAN"); }
    ScanCallback scanCb=new ScanCallback(){ public void onScanResult(int t,ScanResult r){ ingestPhone(r); } public void onBatchScanResults(List<ScanResult> rs){ for(ScanResult r:rs)ingestPhone(r); } };
    void ingestPhone(ScanResult r){ BluetoothDevice dev=r.getDevice(); String addr; try{addr=dev.getAddress();}catch(SecurityException e){addr="unknown";} ScanRecord rec=r.getScanRecord(); String nm=rec!=null&&rec.getDeviceName()!=null?rec.getDeviceName():"(unnamed)"; ingest("PHONE",addr,nm,r.getRssi(),rec==null?Integer.MIN_VALUE:rec.getTxPowerLevel(),rec==null?"":String.valueOf(rec.getServiceUuids()),rec==null?"":rec.getManufacturerSpecificData().toString(),false,null,null); }
    void ingest(String source,String addr,String name,int rssi,int tx,String uuids,String mfg,boolean espGps,Double lat,Double lon){ boolean target=(cfg.mac.length()==0||addr.equalsIgnoreCase(cfg.mac))&&(cfg.name.length()==0||name.toLowerCase().contains(cfg.name.toLowerCase())); if(rssi<cfg.minRssi)return; Device d=devices.getOrDefault(source+":"+addr,new Device(addr)); d.source=source; d.name=name; d.rssi=rssi; d.addRssi(rssi); d.tx=tx; d.dist=Distance.estimate(d.filtered(),tx==Integer.MIN_VALUE?cfg.ref:tx,cfg.pathLoss); d.band=Distance.band(d.dist,d.confidence()); d.tracked=target; d.near=target&&d.dist!=null&&d.dist<=cfg.meters; d.uuids=uuids; d.mfg=mfg; d.count++; d.last=System.currentTimeMillis(); if(d.first==0)d.first=d.last; Location l=bestLoc; if(espGps&&lat!=null&&lon!=null){d.lat=lat;d.lon=lon;d.locSource="ESP32 GPS";} else if(cfg.gps&&l!=null){d.lat=l.getLatitude();d.lon=l.getLongitude();d.locSource="phone GPS fallback";} if(target){ if(sweeping&&!Float.isNaN(heading))d.addSweep(heading,d.filtered()); d.addMovement(l); trackStatus.setText("Tracking "+addr+" • "+(d.near?"NEAR":"out")+" • "+d.rangeText()+" • "+d.confidence()+"% • "+d.bearingText()+" • "+d.moveHint); trackStatus.setTextColor(d.near?GREEN:AMBER); if(d.count%5==1)log("Target "+(d.near?"near":"seen/out")+": "+addr+" "+d.rangeText()+" conf "+d.confidence()+"% "+d.bearingText()+" "+d.moveHint); } devices.put(source+":"+addr,d); }
    void connectEspBle(){ if(espConnected||espScanning){ stopEspBle(); return; } if(!hasPerms()){requestPerms();return;} BluetoothAdapter a=((BluetoothManager)getSystemService(BLUETOOTH_SERVICE)).getAdapter(); if(a==null||!a.isEnabled()){startActivity(new Intent(Settings.ACTION_BLUETOOTH_SETTINGS));return;} ble=a.getBluetoothLeScanner(); if(ble==null){toast("BLE scanner unavailable");return;} espLed.setTextColor(AMBER); espBtn.setText("STOP ESP32 GATT"); note.setText("Scanning for ESP32 Tracker Direct GATT service..."); log("Direct GATT scan started; ESP32 must be in gatt mode"); try{ List<ScanFilter> filters=Collections.singletonList(new ScanFilter.Builder().setServiceUuid(new ParcelUuid(UUID.fromString(ESP_SERVICE))).build()); ble.startScan(filters,new ScanSettings.Builder().setScanMode(ScanSettings.SCAN_MODE_LOW_LATENCY).build(),espScanCb); espScanning=true; h.postDelayed(()->{ if(espScanning){ log("Direct GATT service scan timed out; trying name-based scan fallback"); try{ble.stopScan(espScanCb); ble.startScan(null,new ScanSettings.Builder().setScanMode(ScanSettings.SCAN_MODE_LOW_LATENCY).build(),espScanCb);}catch(Exception ignored){} } },6000); }catch(SecurityException e){espLed.setTextColor(RED); espBtn.setText("DIRECT BLE GATT CONNECT"); log("Direct GATT permission denied: "+e.getMessage());} }
    void stopEspBle(){ if(ble!=null&&espScanning)try{ble.stopScan(espScanCb);}catch(Exception ignored){} espScanning=false; espConnected=false; espRx=null; espTx=null; if(espGatt!=null)try{espGatt.disconnect();espGatt.close();}catch(Exception ignored){} espGatt=null; espLed.setTextColor(RED); if(espBtn!=null)espBtn.setText("DIRECT BLE GATT CONNECT"); }
    ScanCallback espScanCb=new ScanCallback(){ public void onScanResult(int t,ScanResult r){ handleEspScan(r); } public void onBatchScanResults(List<ScanResult> rs){ for(ScanResult r:rs)handleEspScan(r); } };
    void handleEspScan(ScanResult r){ String name=""; ScanRecord rec=r.getScanRecord(); if(rec!=null&&rec.getDeviceName()!=null)name=rec.getDeviceName(); try{ if(name.contains("ESP32 Tracker") || (rec!=null&&rec.getServiceUuids()!=null&&rec.getServiceUuids().contains(new ParcelUuid(UUID.fromString(ESP_SERVICE))))){ ble.stopScan(espScanCb); espScanning=false; BluetoothDevice d=r.getDevice(); log("Direct GATT found "+name+" "+d.getAddress()); espGatt=d.connectGatt(this,false,espGattCb); } }catch(SecurityException e){log("Direct GATT connect permission denied: "+e.getMessage());} }
    BluetoothGattCallback espGattCb=new BluetoothGattCallback(){ public void onConnectionStateChange(BluetoothGatt g,int status,int state){ if(state==BluetoothProfile.STATE_CONNECTED){ espConnected=true; runOnUiThread(()->{espLed.setTextColor(GREEN); note.setText("ESP32 GATT connected; discovering services"); log("Direct GATT connected");}); try{g.discoverServices();}catch(SecurityException e){runOnUiThread(()->log("GATT discover denied: "+e.getMessage()));} } else if(state==BluetoothProfile.STATE_DISCONNECTED){ espConnected=false; espRx=null; espTx=null; runOnUiThread(()->{espLed.setTextColor(RED); espBtn.setText("DIRECT BLE GATT CONNECT"); log("Direct GATT disconnected");}); } } public void onServicesDiscovered(BluetoothGatt g,int status){ BluetoothGattService s=g.getService(UUID.fromString(ESP_SERVICE)); if(s!=null){ espRx=s.getCharacteristic(UUID.fromString(ESP_RX)); espTx=s.getCharacteristic(UUID.fromString(ESP_TX)); runOnUiThread(()->log("Direct GATT service discovered; RX="+(espRx!=null)+" TX="+(espTx!=null))); if(espTx!=null){ try{ g.readCharacteristic(espTx); g.setCharacteristicNotification(espTx,true); BluetoothGattDescriptor d=espTx.getDescriptor(CCCD); if(d!=null){ d.setValue(BluetoothGattDescriptor.ENABLE_NOTIFICATION_VALUE); g.writeDescriptor(d); } }catch(SecurityException e){runOnUiThread(()->log("GATT subscribe denied: "+e.getMessage()));} } } else runOnUiThread(()->log("Direct GATT service not found")); } public void onCharacteristicRead(BluetoothGatt g,BluetoothGattCharacteristic c,int status){ if(status==BluetoothGatt.GATT_SUCCESS)handleGattPayload(c.getValue()); } public void onCharacteristicChanged(BluetoothGatt g,BluetoothGattCharacteristic c){ handleGattPayload(c.getValue()); } };
    void handleGattPayload(byte[] value){ if(value==null||value.length==0)return; String line=new String(value); log("GATT RX "+line.length()+" bytes"); parseRemoteLineWithSource(line,"ESP32-GATT"); }
    boolean writeEspRx(String cmd){ if(espGatt==null||espRx==null)return false; try{ espRx.setValue(cmd.getBytes()); return espGatt.writeCharacteristic(espRx); }catch(SecurityException e){log("GATT write denied: "+e.getMessage()); return false;} }
    void pollWifi(){ if(!wifiPolling)return; new Thread(()->{ try{ HttpURLConnection c=(HttpURLConnection)new URL(cfg.host).openConnection(); c.setConnectTimeout(2500); c.setReadTimeout(2500); BufferedReader br=new BufferedReader(new InputStreamReader(c.getInputStream())); String line; int n=0; while((line=br.readLine())!=null){n++;parseRemoteLine(line);} final int count=n; runOnUiThread(()->{wifiLed.setTextColor(GREEN); log("Wi-Fi poll OK: "+count+" detections");}); }catch(Exception e){runOnUiThread(()->{wifiLed.setTextColor(AMBER); note.setText("Wi-Fi remote waiting: expected JSONL from ESP32 /scan."); log("Wi-Fi poll error: "+e.getMessage());});} h.postDelayed(this::pollWifi,2500); }).start(); }
    void parseRemoteLine(String line){ parseRemoteLineWithSource(line,"ESP32-WIFI"); }
    void parseRemoteLineWithSource(String line,String source){ String addr="ESP32-REMOTE", name="remote", uu="", mf=""; int r=-70, tx=Integer.MIN_VALUE; Double lat=null, lon=null; try{ JSONObject o=new JSONObject(line); addr=o.optString("address",addr); name=o.optString("name",o.optString("local_name",name)); r=o.optInt("rssi",r); tx=o.has("tx")?o.optInt("tx",tx):tx; uu=o.optString("service_uuids",""); mf=o.optString("manufacturer_data",""); if(o.has("lat")&&o.has("lon")){ lat=o.optDouble("lat"); lon=o.optDouble("lon"); } }catch(Exception jsonErr){ String[] p=line.replace("{","").replace("}","").replace("\"","").split(","); for(String part:p){String[] kv=part.split(":",2); String k=kv.length>1?kv[0].trim():"", v=kv.length>1?kv[1].trim():part.trim(); if(k.equals("address")||addr.equals("ESP32-REMOTE"))addr=v; else if(k.equals("name")||k.equals("local_name"))name=v; else if(k.equals("rssi"))try{r=Integer.parseInt(v);}catch(Exception ignored){} else if(k.equals("tx"))try{tx=Integer.parseInt(v);}catch(Exception ignored){} else if(k.equals("lat"))try{lat=Double.parseDouble(v);}catch(Exception ignored){} else if(k.equals("lon"))try{lon=Double.parseDouble(v);}catch(Exception ignored){} else if(k.equals("service_uuids"))uu=v; else if(k.equals("manufacturer_data"))mf=v;} } final String a=addr,n=name,u=uu,m=mf,src=source; final int rr=r,tt=tx; final Double la=lat,lo=lon; runOnUiThread(()->ingest(src,a,n,rr,tt,u,m,la!=null&&lo!=null,la,lo)); }
    void startLocation(){ if(!hasPerms())return; try{ lm.requestLocationUpdates(LocationManager.GPS_PROVIDER,2000,1,this); lm.requestLocationUpdates(LocationManager.NETWORK_PROVIDER,3000,5,this); gpsLed.setTextColor(AMBER); }catch(Exception ignored){} }
    void stopLocation(){ try{lm.removeUpdates(this);}catch(Exception ignored){} gpsLed.setTextColor(bestLoc==null?RED:AMBER); }
    public void onLocationChanged(Location l){ bestLoc=l; gpsLed.setTextColor(GREEN); updateMap(); }
    public void onProviderEnabled(String p){} public void onProviderDisabled(String p){} public void onStatusChanged(String p,int s,Bundle e){}
    void startCompass(){ if(sm==null)return; if(rotSensor!=null)sm.registerListener(this,rotSensor,SensorManager.SENSOR_DELAY_UI); else { if(accSensor!=null)sm.registerListener(this,accSensor,SensorManager.SENSOR_DELAY_UI); if(magSensor!=null)sm.registerListener(this,magSensor,SensorManager.SENSOR_DELAY_UI); } }
    void stopCompass(){ if(sm!=null)sm.unregisterListener(this); }
    public void onAccuracyChanged(Sensor s,int a){}
    public void onSensorChanged(SensorEvent e){ if(e.sensor.getType()==Sensor.TYPE_ROTATION_VECTOR){ float[] r=new float[9],o=new float[3]; SensorManager.getRotationMatrixFromVector(r,e.values); SensorManager.getOrientation(r,o); setHeading(o[0]); } else if(e.sensor.getType()==Sensor.TYPE_ACCELEROMETER){ System.arraycopy(e.values,0,accVals,0,3); hasAcc=true; fallbackHeading(); } else if(e.sensor.getType()==Sensor.TYPE_MAGNETIC_FIELD){ System.arraycopy(e.values,0,magVals,0,3); hasMag=true; fallbackHeading(); } }
    void fallbackHeading(){ if(!hasAcc||!hasMag)return; float[] r=new float[9],i=new float[9],o=new float[3]; if(SensorManager.getRotationMatrix(r,i,accVals,magVals)){ SensorManager.getOrientation(r,o); setHeading(o[0]); } }
    void setHeading(float rad){ heading=(float)((Math.toDegrees(rad)+360)%360); if(compassLed!=null)compassLed.setTextColor(GREEN); if(radar!=null)radar.heading=heading; }
    void toggleSweep(){ sweeping=!sweeping; sweepBtn.setText(sweeping?"STOP COMPASS SWEEP":"START COMPASS SWEEP"); if(sweeping){ for(Device d:devices.values()) if(d.tracked)d.clearSweep(); log("Sweep started; rotate slowly while target remains visible"); } else log("Sweep stopped"); updateSweepStatus(); }
    void updateSweepStatus(){ Device d=trackedDevice(); if(sweepStatus==null)return; sweepStatus.setText((sweeping?"Sweep: recording":"Sweep: off")+" • heading "+(Float.isNaN(heading)?"waiting":String.format(Locale.US,"%.0f°",heading))+" • "+(d==null?"track a target":d.bearingText()+" samples "+d.sweepCount())); }
    Device trackedDevice(){ for(Device d:devices.values()) if(d.tracked)return d; return null; }
    void tick(){ render(); radar.invalidate(); updateMap(); h.postDelayed(this::tick,1000); }
    void render(){ ArrayList<Device> ds=new ArrayList<>(devices.values()); ds.sort((a,b)->Long.compare(b.last,a.last)); updateSweepStatus(); stats.setText((scanning?"Phone scanning":"Phone idle")+" • ESP32 direct "+(espConnected?"connected":"ready")+" • Wi-Fi "+(wifiPolling?"polling":"idle")+" • devices "+ds.size()+" • GPS "+(bestLoc==null?"waiting":"locked")+" • compass "+(Float.isNaN(heading)?"waiting":String.format(Locale.US,"%.0f°",heading))); list.removeAllViews(); for(Device d:ds){ long age=(System.currentTimeMillis()-d.last)/1000; int color=age<6?GREEN:age<20?AMBER:0xff607080; TextView v=t(d.name+"  "+d.addr+"  ["+d.source+"]\nRSSI "+d.rssi+" dBm • median "+d.median()+" • EMA "+String.format(Locale.US,"%.1f",d.ema)+" • noise "+String.format(Locale.US,"%.1f dB",d.noise())+" • samples "+d.count+" • age "+age+"s\nDistance "+d.rangeText()+" • confidence "+d.confidence()+"% • "+d.bearingText()+" • "+d.moveHint+"\nLocation: "+(d.lat==null?"none yet":String.format(Locale.US,"%.6f, %.6f (%s)",d.lat,d.lon,d.locSource))+"\nUUIDs "+d.uuids+"\nMFG "+d.mfg,13,0xffe8fbff,false); v.setBackgroundColor(0x2210d8ff); v.setTextColor(color); list.addView(v); } }
    void updateMap(){ if(map==null)return; map.getOverlays().clear(); if(bestLoc!=null){ GeoPoint me=new GeoPoint(bestLoc.getLatitude(),bestLoc.getLongitude()); map.getController().setCenter(me); Marker m=new Marker(map); m.setPosition(me); m.setTitle("Scanner / phone GPS fallback"); map.getOverlays().add(m); } for(Device d:devices.values()) if(d.lat!=null&&d.lon!=null){ Marker m=new Marker(map); m.setPosition(new GeoPoint(d.lat,d.lon)); m.setTitle(d.name+" " + (d.dist==null?"":String.format(Locale.US,"%.1fm",d.dist))); m.setSubDescription(d.source+" RSSI "+d.rssi+" / "+d.locSource); map.getOverlays().add(m); } map.invalidate(); }

    static class SettingsModel{ int source,transport,minRssi=-100,ref=-59; double meters=5,pathLoss=3.0; String host="http://192.168.4.1/scan",mac="",name=""; boolean gps=true; }
    static class Device{ String addr,name="",source="",uuids="",mfg="",locSource="",band="unknown",moveHint="walk farther for bearing"; int rssi,avg,tx,count; long first,last; boolean tracked,near; Double dist,lat,lon; double ema=Double.NaN,bearing=Double.NaN,bearingScore; Location moveLoc; double moveRssi=Double.NaN; ArrayDeque<Integer> hist=new ArrayDeque<>(); ArrayDeque<SweepSample> sweep=new ArrayDeque<>(); Device(String a){addr=a;} void addRssi(int r){hist.add(r);while(hist.size()>15)hist.remove();int med=median(); ema=Double.isNaN(ema)?med:ema*0.72+med*0.28; avg=(int)Math.round(ema);} double filtered(){return Double.isNaN(ema)?rssi:ema;} int median(){ArrayList<Integer> v=new ArrayList<>(hist); if(v.isEmpty())return rssi; Collections.sort(v); return v.get(v.size()/2);} double noise(){ if(hist.size()<2)return 12; double m=0; for(int x:hist)m+=x; m/=hist.size(); double s=0; for(int x:hist)s+=(x-m)*(x-m); return Math.sqrt(s/hist.size()); } int confidence(){ long age=(System.currentTimeMillis()-last)/1000; int c=100-(int)age*5-(int)(noise()*5)-Math.max(0,8-hist.size())*5; if(Double.isNaN(bearing))c-=8; return Math.max(5,Math.min(98,c)); } String rangeText(){return dist==null?"unknown":String.format(Locale.US,"~%.1f m (%s)",dist,band);} void addSweep(float h,double r){sweep.add(new SweepSample(h,r));while(sweep.size()>80)sweep.remove(); calcBearing();} int sweepCount(){return sweep.size();} void clearSweep(){sweep.clear();bearing=Double.NaN;bearingScore=0;} void calcBearing(){ if(sweep.size()<12)return; SweepSample best=null; double sum=0; for(SweepSample s:sweep){sum+=s.rssi;if(best==null||s.rssi>best.rssi)best=s;} double avg=sum/sweep.size(); if(best!=null&&best.rssi-avg>=3.0){bearing=best.heading;bearingScore=Math.min(99,(best.rssi-avg)*12+sweep.size()/2);} } String bearingText(){ return Double.isNaN(bearing)?"bearing hint unavailable / angle visual":String.format(Locale.US,"strongest-signal heading %.0f° %s conf %.0f%%",bearing,dir(bearing),bearingScore); } void addMovement(Location l){ if(l==null)return; if(moveLoc==null){moveLoc=new Location(l); moveRssi=filtered(); return;} float meters=l.distanceTo(moveLoc); double diff=filtered()-moveRssi; if(meters>=8&&Math.abs(diff)>=3){ double b=moveLoc.bearingTo(l); moveHint=(diff>0?"signal improving toward ":"signal weaker walking ")+dir((b+360)%360); moveLoc=new Location(l); moveRssi=filtered(); } } static String dir(double d){String[] dirs={"N","NE","E","SE","S","SW","W","NW"}; return dirs[(int)Math.round((((d%360)+360)%360)/45.0)%8];} }
    static class SweepSample{ double heading,rssi; SweepSample(double h,double r){heading=h;rssi=r;} }
    static class Distance{ static Double estimate(double rssi,int ref,double n){ if(rssi==0)return null; double d=Math.pow(10.0,(ref-rssi)/(10*n)); return Math.max(0.3,Math.min(80,d)); } static String band(Double d,int c){ if(d==null||c<20)return "unknown"; if(d<1.5)return "very near"; if(d<6)return "near"; if(d<20)return "medium"; return "far"; } }
    public static class RadarView extends View{ Paint p=new Paint(1); Map<String,Device> devices; long start=System.currentTimeMillis(); float heading=Float.NaN; public RadarView(Context c){super(c);} protected void onDraw(Canvas c){ int w=getWidth(),h=getHeight(),cx=w/2,cy=h/2; p.setStyle(Paint.Style.FILL); p.setShader(new RadialGradient(cx,cy,w/2,0xff102033,BG, Shader.TileMode.CLAMP)); c.drawRect(0,0,w,h,p); p.setShader(null); p.setStyle(Paint.Style.STROKE); p.setStrokeWidth(2); p.setColor(0x6600e5ff); int maxR=Math.min(w,h)/2-36; for(int i=1;i<=4;i++){int r=maxR*i/4;c.drawCircle(cx,cy,r,p);} p.setStyle(Paint.Style.FILL); p.setColor(0xff9db2c0); p.setTextSize(22); c.drawText("Calibrated RSSI bands: very near / near / medium / far • bearing is hint only",18,34,p); p.setStrokeWidth(5); p.setColor(0xaa00e5ff); float a=Float.isNaN(heading)?((System.currentTimeMillis()-start)%3600)/10f:heading-90; c.drawLine(cx,cy,cx+(float)Math.cos(Math.toRadians(a))*maxR,cy+(float)Math.sin(Math.toRadians(a))*maxR,p); if(devices==null)return; for(Device d:devices.values()){ double meters=d.dist==null?80:d.dist; double norm=Math.min(1, meters/80.0); double deg=Double.isNaN(d.bearing)?Math.abs(d.addr.hashCode())%360:d.bearing-90; double ang=Math.toRadians(deg); float x=cx+(float)Math.cos(ang)*(float)(norm*maxR); float y=cy+(float)Math.sin(ang)*(float)(norm*maxR); int conf=d.confidence(); int alpha=Math.max(70,Math.min(255,conf*2+40)); p.setStyle(Paint.Style.STROKE); p.setStrokeWidth(3); p.setColor((alpha<<24)|0x00ffffff); float unc=(float)(18+d.noise()*4+(100-conf)/2); c.drawCircle(x,y,unc,p); if(d.tracked&&!Double.isNaN(d.bearing)){ p.setStyle(Paint.Style.FILL); p.setColor(0x3341f28f); RectF oval=new RectF(cx-maxR,cy-maxR,cx+maxR,cy+maxR); c.drawArc(oval,(float)d.bearing-105,30,true,p); } p.setStyle(Paint.Style.FILL); p.setColor(conf>70?GREEN:conf>35?AMBER:RED); c.drawCircle(x,y,10+conf/15,p); p.setStyle(Paint.Style.STROKE); p.setColor(0xffffffff); c.drawOval(new RectF(x-18,y-18,x+18,y+18),p); p.setStyle(Paint.Style.FILL); p.setColor(0xffe8fbff); p.setTextSize(20); c.drawText((d.name.length()>9?d.name.substring(0,9):d.name)+" "+d.rangeText(),x+18,y,p); } } }
